from __future__ import annotations

from relocation_jobs.scrape.relevance import is_relevant


def filter_relevant_jobs(
    jobs: list[dict],
    relevant_only: bool,
    *,
    include: list[str] | None = None,
    exclude: list[str] | None = None,
) -> list[dict]:
    out: list[dict] = []
    for job in jobs:
        title = (job.get("title") or "").strip()
        url = (job.get("url") or "").strip()
        if not title or not url:
            continue
        if relevant_only:
            if include is None or exclude is None:
                raise TypeError("include and exclude required when relevant_only")
            if not is_relevant(title, include=include, exclude=exclude):
                continue
        entry = {"title": title, "url": url}
        location = (job.get("location") or "").strip()
        if location:
            entry["location"] = location
        if job.get("locations") is not None:
            entry["locations"] = job["locations"]
        employer = (job.get("employer") or "").strip()
        if employer:
            entry["employer"] = employer
        description = (job.get("description_text") or "").strip()
        if description:
            entry["description_text"] = description
        out.append(entry)
    return out

from __future__ import annotations

from collections import defaultdict

from relocation_jobs.catalog.repo import sync_aggregator_employer_jobs
from relocation_jobs.fetch.log import log_event
